def next_element(n):
    """Calculate the next element in the series based on the rules provided."""
    if n < 10:
        return n + n
    else:
        digits = [int(d) for d in str(n) if d != '0']
        product = 1
        for d in digits:
            product *= d
        return n + product

def is_converged(n):
    """Check if the current number is in the base series."""
    base_series = {1, 2, 4, 8, 16, 22, 26, 38, 62, 74, 102, 104, 108, 116, 122}
    return n in base_series

def generate_series(seed):
    """Generate the test series starting from the given seed."""
    series = [seed]
    while not is_converged(series[-1]):
        series.append(next_element(series[-1]))
    return series

def convergence(n):
    """Return the number of integers generated in the test series before it converges to the base series."""
    series = generate_series(n)
    return len(series)
